import type { AvatarContextType } from "../avatar.types";

import { createContext, useContext } from "react";

export const AvatarContext = createContext<AvatarContextType | null>(null);

export const useAvatar = () => {
  const context = useContext(AvatarContext);
  if (!context) {
    throw new Error("Avatar compound components cannot be rendered outside the Avatar component");
  }
  return context;
};
